package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.os.SystemClock;import android.widget.RemoteViews;
public class AlarmCountdownWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_alarm_countdown);long at=AlarmScheduler.nextTriggerMillis(c);if(at>0){long base=SystemClock.elapsedRealtime()+Math.max(0,at-System.currentTimeMillis());r.setChronometer(R.id.widget_chrono,base,null,true);if(android.os.Build.VERSION.SDK_INT>=24)r.setChronometerCountDown(R.id.widget_chrono,true);r.setTextViewText(R.id.widget_detail,I18n.tr(c,"次のアラーム")+" · "+WidgetSuite.date(c,at));}else{r.setChronometer(R.id.widget_chrono,SystemClock.elapsedRealtime(),null,false);r.setTextViewText(R.id.widget_chrono,"--:--");r.setTextViewText(R.id.widget_detail,I18n.tr(c,"アラームなし"));}r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,MainActivity.class,null,null,24000+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
